import torch, b200probe, inspect
from b200probe import cuda_kernel, harness_time
src = r'''
extern "C" __global__ void k1(const float4* __restrict__ x, float4* __restrict__ h, long n4x){
  long i = blockIdx.x*(long)blockDim.x + threadIdx.x;
  long stride = (long)gridDim.x*blockDim.x;
  for (; i < n4x; i += stride){
    float4 v = x[i];
    long b = i*4;
    #pragma unroll
    for(int j=0;j<4;j++){ float4 w=v; w.x+=j; h[b+j]=w; }
  }
}
extern "C" __global__ void k2(const float4* __restrict__ h, float4* __restrict__ o, long n4o){
  long i = blockIdx.x*(long)blockDim.x + threadIdx.x;
  long stride = (long)gridDim.x*blockDim.x;
  for (; i < n4o; i += stride){
    long b=i*4; float4 a=h[b],c=h[b+1],d=h[b+2],e=h[b+3];
    float4 r; r.x=a.x+c.x+d.x+e.x; r.y=a.y+c.y; r.z=d.z+e.z; r.w=a.w+e.w; o[i]=r;
  }
}
'''
K1 = cuda_kernel(src, "k1"); K2 = cuda_kernel(src, "k2")
print(inspect.signature(harness_time))
for (B,HW) in [(64,3136),(32,3136),(16,3136),(32,784)]:
    N=B*HW
    x=torch.randn(N,128,device='cuda'); h=torch.empty(N,512,device='cuda'); o=torch.empty(N,128,device='cuda')
    n4=N*32
    def fn(x,h,o):
        K1((148*8,),(256,),x,h,n4)
        K2((148*8,),(256,),h,o,n4)
    def fn1(x,h,o):
        K1((148*8,),(256,),x,h,n4)
    t=harness_time(fn,[x],[h,o]); t1=harness_time(fn1,[x],[h,o])
    print(B,HW,N,"both %.1f us  k1 %.1f us  bytes %.0f MB  BW %.2f TB/s"%(t,t1,N*5120/1e6,N*5120/t/1e6))

