        }
#pragma unroll
        for (int m = 0; m < 4; m++) {
          const int ti = i - 2 * m;
          if (ti >= 0 && ti < 7) {
#pragma unroll
            for (int cc = 0; cc < 4; cc++)
#pragma unroll
