#pragma unroll
      for (int m = 0; m < 4; m++)
#pragma unroll
        for (int cc = 0; cc < 4; cc++) { ps[4 * m + cc] = acc[m][cc]; pq[4 * m + cc] = acc[m][cc] * acc[m][cc]; }
