  constexpr int NR = 2 * T;
  const int fs = (T == 1) ? 0 : (g4 >> 1);
  const int fr0 = (T == 1) ? 2 * g4 : (g4 & 1) * 4;
  size_t foff = 0;
  float4 xres[2 * NR];
  float bb = 0.f;
