  tc_after();
#pragma unroll 1
  for (int s = 0; s < T; s++) {
    const int slot = ((tile0 + s) / 49 != img0) ? 1 : 0;
#pragma unroll 1
    for (int i = 0; i < 3; i++) {
      const int u = 3 * g4 + i, b = u >> 2, c16 = (u & 3) * 16;
      const int k = 128 * b + 32 * q4 + lane;
      float a[16];
      tmem_ld16(tmem + ((uint32_t)(32 * q4) << 16) + 192 * s + 64 * b + c16, a);
      const float sc = s_ss[slot * 384 + k];
      uint32_t pk[8];
